"""Build the profile README using only the Python standard library."""

import argparse
import json
import os
from pathlib import Path
import re
import sys
import tempfile


ROOT = Path(__file__).resolve().parent.parent
HEADER = (
    "<!-- Generated by scripts/build_readme.py. "
    "Edit modules/ and profile.config.json; see docs/SETUP.md. -->"
)
MODULE_NAME = re.compile(r"[a-z][a-z0-9_-]*")


class BuildError(ValueError):
    """An invalid source must never replace the existing README."""


def unique_keys(pairs):
    """Reject duplicate JSON keys rather than silently accepting the last one."""
    result = {}
    for key, value in pairs:
        if key in result:
            raise BuildError(f"Duplicate JSON key: {key!r}")
        result[key] = value
    return result


def render(root):
    """Validate all configured modules before returning UTF-8/LF output bytes."""
    config = json.loads(
        (root / "profile.config.json").read_text(encoding="utf-8-sig"),
        object_pairs_hook=unique_keys,
    )
    if not isinstance(config, dict) or set(config) != {"modules"}:
        raise BuildError("Config must contain only a 'modules' array.")
    modules = config["modules"]
    if not isinstance(modules, list) or not modules:
        raise BuildError("'modules' must be a non-empty array.")

    modules_dir = (root / "modules").resolve()
    if not modules_dir.is_relative_to(root):
        raise BuildError("The modules directory must stay inside the repository.")

    seen = set()
    sections = []
    for index, module in enumerate(modules, start=1):
        if not isinstance(module, dict) or set(module) != {"name", "enabled"}:
            raise BuildError(f"Module {index} must contain only 'name' and 'enabled'.")
        name = module["name"]
        if not isinstance(name, str) or not MODULE_NAME.fullmatch(name):
            raise BuildError(f"Module {index} has an invalid name.")
        if name in seen:
            raise BuildError(f"Duplicate module: {name!r}")
        seen.add(name)
        if type(module["enabled"]) is not bool:
            raise BuildError(f"Module {name!r}: 'enabled' must be true or false.")

        path = (modules_dir / f"{name}.md").resolve()
        if not path.is_relative_to(modules_dir) or not path.is_file():
            raise BuildError(f"Module {name!r} must be a file inside modules/.")
        # Universal newline reading accepts LF, CRLF and CR. Preserve Markdown's
        # intentional indentation and trailing spaces inside each module.
        content = path.read_text(encoding="utf-8-sig").strip("\n")
        if not content.strip() or "\x00" in content:
            raise BuildError(f"Module {name!r} must contain non-empty Markdown without NUL.")
        # Disabled modules are also validated so enabling them is predictable.
        if module["enabled"]:
            sections.append(content)

    if not sections:
        raise BuildError("At least one module must be enabled.")
    return (HEADER + "\n\n" + "\n\n".join(sections) + "\n").encode("utf-8")


def atomic_write(path, content):
    """Write beside the destination and replace only after the write succeeds."""
    temporary_path = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb", dir=path.parent, prefix=".README.", suffix=".tmp", delete=False
        ) as temporary:
            temporary_path = Path(temporary.name)
            temporary.write(content)
            temporary.flush()
            os.fsync(temporary.fileno())
        os.replace(temporary_path, path)
    finally:
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="Check for stale/missing README without writing."
    )
    args = parser.parse_args(argv)

    try:
        expected = render(ROOT)
        output = ROOT / "README.md"
        current = output.read_bytes() if output.exists() else None
        if current == expected:
            print("README.md is up to date; no write needed.")
            return 0
        if args.check:
            print("README.md is missing or out of date. Run: python scripts/build_readme.py")
            return 1
        atomic_write(output, expected)
        print("README.md updated.")
        return 0
    except (OSError, ValueError, UnicodeError) as error:
        print(f"Build failed; README.md was not replaced: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
